mapper.select:
SELECT /*LGSYSC00180.retrieveMenuList*/ MENU_ID, MENU_NAME, SYSTEM_CODE, MODULE_CODE, HIGH_MENU_ID, PROGRAM_ID, MENU_DESC, PROGRAM_ID, PROGRAM_NAME, MENU_URL_ADDR, MENU_LEVEL_NO, SORT_ORDER_NO, DISPLAY_FLAG, USE_FLAG, POP_UP_SCREEN_FLAG FROM LGCOM_MENU_M_V T WHERE LANGUAGE_CODE = #{USER_SESSION.languageCode} AND SYSTEM_CODE = #{systemCode}
AND MODULE_CODE = #{moduleCode}
AND MENU_ID IN ( SELECT MENU_ID FROM LGCOM_MENU_M A START WITH A.MENU_NAME LIKE '%'||#{menuName}||'%' CONNECT BY ( PRIOR A.HIGH_MENU_ID = A.MENU_ID ) )
ORDER BY MENU_ORDER_BY

SELECT /*LGSYSC00180.retrieveProgramList*/ SYSTEM_CODE, MODULE_CODE, PROGRAM_ID, PROGRAM_NAME FROM LGCOM_PROGRAM_M WHERE USE_FLAG = 'Y'
AND SYSTEM_CODE = #{systemCode}
AND MODULE_CODE = #{moduleCode}
AND PROGRAM_ID LIKE '%'||#{programId}||'%'
AND PROGRAM_NAME LIKE '%'||#{programName}||'%'
ORDER BY SYSTEM_CODE, MODULE_CODE, PROGRAM_ID

mapper.update:
/*LGSYSC00180.deleteMenu*/
    DELETE FROM LGCOM_MENU_M
     WHERE MENU_ID = #{menuId}
       AND SYSTEM_CODE = #{systemCode}
       AND MODULE_CODE = #{moduleCode}

mapper.select:
   /*LGSYSC00180.retrieveNewMenuId*/	
	SELECT 'M_' || #{moduleCode} || '_' ||
	       (NVL(MAX(SUBSTR(menu_id, INSTR(MENU_ID,'_', 1, 2)+1) + 1), '1001')) AS MENU_ID
	  FROM LGCOM_MENU_M
	 WHERE SYSTEM_CODE = #{systemCode}
	   AND MODULE_CODE = #{moduleCode}

mapper.insert:
/*LGSYSC00180.insertMenu*/
INSERT INTO LGCOM_MENU_M
   ( MENU_ID
    ,SYSTEM_CODE
    ,MODULE_CODE
    ,HIGH_MENU_ID
    ,MENU_NAME
    ,MENU_DESC
    ,PROGRAM_ID
    ,URL_ADDR
    ,MENU_LEVEL_NO
    ,SORT_ORDER_NO
    ,DISPLAY_FLAG
    ,USE_FLAG
    ,POP_UP_SCREEN_FLAG
    ,MENU_SEQ_NO
    ,CREATED_BY
    ,CREATION_DATE
    ,LAST_UPDATED_BY
    ,LAST_UPDATE_DATE  )
  VALUES 
  ( #{menuId}
    ,#{systemCode}
    ,#{moduleCode}
    ,DECODE( #{menuLevelNo}, '1', null, #{highMenuId} )
    ,#{menuName}
    ,#{menuDesc}
    ,#{programId}
    ,#{urlAddr}
    ,#{menuLevelNo}
    ,#{sortOrderNo}
    ,#{displayFlag}
    ,#{useFlag}
    ,#{popUpScreenFlag}
    ,LGCOM_MENU_M_SEQ.NEXTVAL
    ,#{USER_SESSION.applicationUserId}
    ,SYSDATE
    ,#{USER_SESSION.applicationUserId}
    ,SYSDATE  )
